import { Component } from '@angular/core';
import { FeaturesManagementService } from 'app/services/features-management';
import { I360Config } from 'app/utils/config/config';
import { Panel } from 'app/utils/panel';
import { map, of, Observable } from 'rxjs';

@Component({
    selector: 'features-management',
    templateUrl: './wrapper.component.html',
})
export class FeaturesManagementWrapperComponent {
    pleskServicePlanEnabled$: Observable<boolean | undefined> = of(false);

    constructor(
        public panel: Panel,
        public featuresManagementService: FeaturesManagementService,
        public config: I360Config,
    ) {
        if (this.panel.isPlesk) {
            this.pleskServicePlanEnabled$ = this.config.changes.pipe(
                map(config => config.PERMISSIONS?.use_plesk_service_plan),
            );
        }
    }
}
