import { Component, Input } from '@angular/core';
import { Product } from '@imunify360-api/license';
import { LicenseState } from 'app/services/license-state';
import { Panel } from 'app/utils/panel';
import { useLoader } from 'app/utils/loader/decorators';
import { firstValueFrom } from 'rxjs';
import { ModalService } from 'app/utils/modals/modal.service';
import { SettingsService } from 'app/services/settings';


@Component({
    selector: 'features-management-native',
    styleUrls: ['./native.component.scss'],
    templateUrl: './native.component.html',
})
export class FeaturesManagementNativeComponent {
    Product = Product;
    packageName = IMUNIFY_PACKAGE;
    t = 'settings.featuresManagement.newFeaturesManagement.featuresManagementDisabled.';
    @Input() isMyImunify: boolean;

    constructor(
        public licenseState: LicenseState,
        public panel: Panel,
        private modalService: ModalService,
        private settingsService: SettingsService,
    ) {}

    public confirmSwitchToImunify(): void {
        this.modalService.confirm('switch-back-to-imunify-feature-management', [])
            .then((result: boolean) => {
                if (result) {
                    this.disablePleskServicePlans()
                        .then(() => {
                            location.reload();
                        });
                }
            });
    }

    @useLoader
    private disablePleskServicePlans() {
        const patch = {
            PERMISSIONS: { use_plesk_service_plan: false }
        };

        return firstValueFrom(this.settingsService.saveSettings(patch));
    }
}
