import { Component, forwardRef, OnDestroy } from '@angular/core';
import { DEFAULT_EMAIL } from '@imunify360-api/notification-settings';
import { NG_VALUE_ACCESSOR, ControlValueAccessor, FormControl } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

@Component({
    selector: 'i360-notification-emails',
    templateUrl: './notification-emails.component.html',
    host: {
        '[class.config_item]': 'true',
        '[class.flexer]': 'true',
    },
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => SettingsNotificationEmailsComponent),
            multi: true,
        },
    ],
})
export class SettingsNotificationEmailsComponent implements ControlValueAccessor, OnDestroy {
    adminEmailsControl = new FormControl<string[]>([]);
    useDefaultEmails = false;

    useDefaultEmailsChange(value: boolean): void {
        const adminEmails = this.adminEmailsControl.getRawValue() || [];

        if (value) {
            this.adminEmailsControl?.setValue([...adminEmails, DEFAULT_EMAIL]);
        } else {
            const filtered= adminEmails.filter((email: string) => email !== DEFAULT_EMAIL);
            this.adminEmailsControl?.setValue([...filtered]);
        }

        this.useDefaultEmails = value;
    }

    private destroy$ = new Subject<void>();

    onChange: (value: string[]) => void;
    onTouched: () => void;

    writeValue(value: string[]): void {
        if (value) {
            this.useDefaultEmails = value.some((email: string) => {
                return email === DEFAULT_EMAIL;
            });
        }
        this.adminEmailsControl.setValue(value || [], { emitEvent: false });
    }

    registerOnChange(fn: any): void {
        this.onChange = fn;
        this.adminEmailsControl.valueChanges.pipe(takeUntil(this.destroy$)).subscribe(fn);
    }

    registerOnTouched(fn: any): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        if (isDisabled) {
            this.adminEmailsControl.disable();
        } else {
            this.adminEmailsControl.enable();
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next();
    }
}
