import { Component, forwardRef, OnDestroy } from '@angular/core';
import { ControlValueAccessor, FormControl, NG_VALUE_ACCESSOR } from '@angular/forms';
import { SeparatedBy } from 'app/utils/comma-separated-input/comma-separated-input.directive';
import { takeUntil } from 'rxjs/operators';
import { Subject } from 'rxjs';

@Component({
    selector: 'i360-notification-run-script',
    templateUrl: './notification-run-script.component.html',
    host: {
        '[class.config_item]': 'true',
        '[class.flexer]': 'true',
    },
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => SettingsNotificationRunScriptComponent),
            multi: true,
        },
    ],
})
export class SettingsNotificationRunScriptComponent implements ControlValueAccessor, OnDestroy {
    scriptsControl = new FormControl<string[]>([]);
    SeparatedBy = SeparatedBy;
    private destroy$ = new Subject<void>();

    onChange: (value: string[]) => void;
    onTouched: () => void;

    writeValue(value: string[]): void {
        this.scriptsControl.setValue(value || [], { emitEvent: false });
    }

    registerOnChange(fn: any): void {
        this.onChange = fn;
        this.scriptsControl.valueChanges.pipe(takeUntil(this.destroy$)).subscribe(fn);
    }

    registerOnTouched(fn: any): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        if (isDisabled) {
            this.scriptsControl.disable();
        } else {
            this.scriptsControl.enable();
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next();
    }
}
